The relation between the Stokes coefficients in \eqref{ell-linear-aliender-1}--\eqref{ell-linear-aliender-3} and the Borel residues in \eqref{ellipticBPhiiSij} can be easily determined following the example\footnote{This was dubbed the ``explicit (linear) example'' in appendix~\ref{app:alien-calculus}.} outlined in appendix~\ref{app:alien-calculus}; or else along the very general lines discussed earlier in sections~\ref{sec:quartic} and~\ref{sec:physics}. It is simple to find:

\begin{align}
\label{eq:nonres-Borel-stokes-01}
&\mathsf{S}_{0\to 1} = - S_{\omega_{01}}, 
&&\mathsf{S}_{1\to 0} = - S_{\omega_{10}}, \\
&\mathsf{S}_{0\to 2} = - S_{\omega_{02}}, 
&&\mathsf{S}_{2\to 0} = - S_{\omega_{20}}, \\
&\mathsf{S}_{1\to 2} = - S_{\omega_{12}} - \frac{1}{2}\, S_{\omega_{10}}\,S_{\omega_{02}}, 
&&\mathsf{S}_{2\to 1} = - S_{\omega_{21}} - \frac{1}{2}\, S_{\omega_{20}}\,S_{\omega_{01}}.
\label{eq:nonres-Borel-stokes-21}
\end{align}

The next step is to determine the Stokes automorphism, given by \eqref{stokesauto} and explicitly in \eqref{Stokes-aut-as exponential-singularities}, along all possible singular directions. This essentially follows from the alien derivatives \eqref{ell-linear-aliender-1}--\eqref{ell-linear-aliender-3}. Possible singular directions may depend on the value of the modular parameter $m$, and to make things simpler we will only have in mind the case of $m\in(0,1)$ already depicted in figure~\ref{linear-algebraic-structure-elliptic}. The Stokes automorphism at $\theta=0$ is

\begin{equation}
\label{eq:disc-Z-0}
\underline{\mathfrak{S}}_0 = \exp \left( {\mathrm{e}}^{-\frac{\omega_{01}}{x}} \Delta_{\omega_{01}} + {\mathrm{e}}^{-\frac{\omega_{20}}{x}} \Delta_{\omega_{20}} + {\mathrm{e}}^{-\frac{\omega_{21}}{x}} \Delta_{\omega_{21}} \right).
\end{equation}

\noindent
As expected, only the alien derivatives whose associated relative actions are positive (\textit{i.e.}, $\omega_{01}$, $\omega_{20}$, $\omega_{21}$) contribute to the discontinuity along $\theta=0$, albeit not all will act non-trivially on each sector $\Phi_i$. Similarly, for $\theta=\pi$ we get

\begin{equation}
\label{eq:disc-Z-pi}
\underline{\mathfrak{S}}_\pi = \exp \left( {\mathrm{e}}^{-\frac{\omega_{10}}{x}} \Delta_{\omega_{10}} + {\mathrm{e}}^{-\frac{\omega_{02}}{x}} \Delta_{\omega_{02}}+ {\mathrm{e}}^{-\frac{\omega_{12}}{x}} \Delta_{\omega_{12}} \right),
\end{equation}

\noindent
with only the negative relative actions $\omega_{10}$, $\omega_{02}$, $\omega_{12}$ contributing. Acting on each asymptotic sector $\Phi_i$, via expansion of the exponentials in \eqref{eq:disc-Z-0} and \eqref{eq:disc-Z-pi} (which collapse to finite sums), and further using \eqref{ell-linear-aliender-1}--\eqref{ell-linear-aliender-3}, it simply follows:

\begin{eqnarray}
\label{ell-linear-Stokes-00}
\underline{\mathfrak{S}}_0 \Phi_0 &=& \Phi_0 + S_{\omega_{01}}\, \mathrm{e}^{-\frac{A_1}{x}}\, \Phi_1 = \Phi_0 - \mathsf{S}_{0\to 1}\, \mathrm{e}^{-\frac{A_1}{x}}\, \Phi_1, \\
\label{ell-linear-Stokes-pi0}
\underline{\mathfrak{S}}_{\pi} \Phi_0 &=& \Phi_0 + S_{\omega_{02}}\, \mathrm{e}^{-\frac{A_2}{x}}\, \Phi_2 = \Phi_0 - \mathsf{S}_{0\to 2}\, \mathrm{e}^{-\frac{A_2}{x}}\, \Phi_2, \\
\label{ell-linear-Stokes-pi1}
\underline{\mathfrak{S}}_{\pi} \Phi_1 &=& \Phi_1 + S_{\omega_{10}}\, \mathrm{e}^{+\frac{A_1}{x}}\, \Phi_0 + \left( S_{\omega_{12}} + \frac{1}{2} S_{\omega_{02}} S_{\omega_{10}} \right) \mathrm{e}^{+\frac{A_1-A_2}{x}}\, \Phi_2 \nonumber \\
&=& \Phi_1 - \mathsf{S}_{1\to 0}\, \mathrm{e}^{+\frac{A_1}{x}}\, \Phi_0 - \mathsf{S}_{1\to 2}\, \mathrm{e}^{+\frac{A_1-A_2}{ x}}\, \Phi_2, \\
\label{ell-linear-Stokes-02}
\underline{\mathfrak{S}}_0 \Phi_2 &=& \Phi_2 + S_{\omega_{20}}\, \mathrm{e}^{+\frac{A_2}{x}}\, \Phi_0 + \left( S_{\omega_{21}} + \frac{1}{2} S_{\omega_{01}} S_{\omega_{20}} \right) \mathrm{e}^{-\frac{A_1-A_2}{x}}\, \Phi_1 \nonumber \\
&=& \Phi_2 - \mathsf{S}_{2\to 0}\, \mathrm{e}^{+\frac{A_2}{x}}\, \Phi_0 - \mathsf{S}_{2\to 1}\, \mathrm{e}^{-\frac{A_1-A_2}{x}}\, \Phi_1,
\end{eqnarray}

\noindent
where we made use of the relations \eqref{eq:nonres-Borel-stokes-01}--\eqref{eq:nonres-Borel-stokes-21} to display all results with either Stokes coefficients or Borel residues. These expressions encode Stokes phenomena across all Stokes lines. The lateral resummations across these lines, \eqref{stokesauto}, applied to the transseries \eqref{ell_lin_transseries-v2} can be easily written down, from where one obtains the \textit{Stokes transitions}

\begin{eqnarray}
\label{ell-stokes-transitions-0}
\mathcal{S}_{0^+} \mathcal{Z} \left( x, \sigma_0, \sigma_1, \sigma_2 \right) &=& \mathcal{S}_{0^-} \mathcal{Z} \left( x,\, \sigma_0-\mathsf{S}_{2\to 0}\,\sigma_2,\, \sigma_1-\mathsf{S}_{0\to 1}\,\sigma_0 - \mathsf{S}_{2\to 1}\,\sigma_2,\, \sigma_2 \right), \\
\label{ell-stokes-transitions-pi}
\mathcal{S}_{\pi^+} \mathcal{Z} \left( x, \sigma_0, \sigma_1, \sigma_2 \right) &=& \mathcal{S}_{\pi^-} \mathcal{Z} \left( x,\, \sigma_0-\mathsf{S}_{1\to 0}\,\sigma_1,\, \sigma_1,\, \sigma_2-\mathsf{S}_{0\to 2}\,\sigma_0-\mathsf{S}_{1\to 2}\,\sigma_1 \right).
\end{eqnarray}

\noindent
For simplicity, we have written the Stokes transitions in terms of the Borel residues. The same expressions in terms of the Stokes coefficients may be easily obtained from \eqref{eq:nonres-Borel-stokes-01}--\eqref{eq:nonres-Borel-stokes-21}.

By comparing the Stokes transitions with the jumps of the steepest-descent contours encoded in the Stokes matrices \eqref{ell-monodromy-0} and \eqref{ell-monodromy-pi}, one can easily determine the value of the Borel residues and Stokes coefficients. The jump of a given contour $\mathcal{J}_i$ across a Stokes ray will correspond to the jump of the corresponding asymptotic sector $Z^{(i)}$ in the Stokes transition. For $\theta=0$ one has (compare with \eqref{ell-monodromy-0})

\begin{equation}
\left(
\begin{array}{ccc}
Z^{(2)} \\
Z^{(0)} \\
Z^{(1)}
\end{array}
\right) \to S_{\circlearrowleft}^{(0)} \left(
\begin{array}{ccc}
Z^{(2)} \\
Z^{(0)} \\
Z^{(1)}
\end{array}
\right) = \left(
\begin{array}{ccc}
1 & -\mathsf{S}_{2\to 0} & - \mathsf{S}_{2\to 1} \\
0 & 1 & -\mathsf{S}_{0\to 1} \\
0 & 0 & 1
\end{array}
\right) \left(
\begin{array}{ccc}
Z^{(2)} \\
Z^{(0)} \\
Z^{(1)}
\end{array}
\right),
\end{equation}

\noindent
from where we can read the Borel residues $\mathsf{S}_{2\to 0} = \mathsf{S}_{2\to 1} = -\mathsf{S}_{0\to 1} = 2$. The exact same reasoning applied at $\theta=\pi$ yields $\mathsf{S}_{0\to 2} = -\mathsf{S}_{1\to 2} = -\mathsf{S}_{1\to 0} = -2$. Finally, using \eqref{eq:nonres-Borel-stokes-01}--\eqref{eq:nonres-Borel-stokes-21}, one obtains the complete set of Stokes coefficients,

\begin{equation}
S_{\omega_{01}} = 2, 
\qquad 
S_{\omega_{10}} = -2, 
\qquad
S_{\omega_{02}} = 2, 
\qquad
S_{\omega_{20}} = -2, 
\qquad
S_{\omega_{12}} = 0 = S_{\omega_{21}}.
\label{eq:linear-stokes}
\end{equation}

With these numbers in hand, computing monodromies is now straightforward. In fact, moving twice around the origin, \textit{i.e.}, acting with $\left( \underline{\mathfrak{S}}_{\pi} \underline{\mathfrak{S}}_0 \right)^2$ upon the transseries, the parameters $\sigma_i$ get mapped onto themselves. In other words,

\begin{equation}
\left( \underline{\mathfrak{S}}_{\pi} \underline{\mathfrak{S}}_0 \right)^2 = \boldsymbol{1},
\end{equation}

\noindent
which encompasses the monodromy encoded in the transseries solution for the elliptic partition function; once again leading to a multi-sheeted Riemann surface (compare with \eqref{quarticmonodromy}).

It is also very instructive to analyze the resurgent relations between the different sectors $\Phi_i$ purely from the perspective of the Picard--Lefschetz theory introduced in section~\ref{sec:lefschetz} (and further using the main discussion from section~\ref{sec:borel}, as will be clear momentarily). Each asymptotic series in \eqref{eq:elliptic_coeffs0} through \eqref{eq:elliptic_coeffs2} is basically dictated by the small $x\equiv\hbar$ expansion of the integral \eqref{elliptic_Z} evaluated on the appropriate thimble $\Gamma_i$, \textit{i.e.}, the one associated with the critical point $z^*_i$. The calculation is rather straightforward thanks to the elliptic identities

\begin{eqnarray}
\frac{{\mathrm{d}}}{{\mathrm{d}} z} \mathrm{sd} (z | m) &=& \mathrm{nd} (z | m)\, \mathrm{cd} (z | m), \\
\mathrm{nd}^2 (z | m) &=& 1 + m\, \mathrm{sd}^2 (z | m), \\
\mathrm{cd}^2 (z | m) &=& 1 - m^\prime\, \mathrm{sd}^2 (z | m).
\end{eqnarray}

\noindent
Using these identities and the change of variables $s \equiv \mathrm{sd}^2 (z | m)$---which is of the type discussed in section~\ref{sec:borel}; recall \eqref{eq:Change-of-variables-to-Borel}---the integration over the cycle ${\cal J}_0 (\theta)$ may be expressed as 

\begin{equation}
\label{JA}
\frac{1}{\sqrt{\pi x}} \int_{{\cal J}_0(\theta)} {\mathrm{d}} z\, {\mathrm{e}}^{-\frac{1}{x}\, \mathrm{sd}^2 (z | m)} = \frac{1}{\sqrt{\pi x}} \int_0^{{\mathrm{e}}^{{\mathrm{i}}\theta}\infty} {\mathrm{d}} s\, \frac{{\mathrm{e}}^{-\frac{s}{x}}}{\sqrt{s \left( 1 - m^\prime s \right) \left( 1 + m s \right)}} \simeq {\mathrm{e}}^{-\frac{A_0}{x}} \sum_{n=0}^{+\infty} Z^{(0)}_n (m)\, x^n,
\end{equation}

\noindent
where, in the third step, we formally Taylor-expanded the denominator outside its radius of convergence and carried out the resulting $s$-integration, leading to the  asymptotic perturbative expansion $\Phi_0(x)$. In this way, it should not come as a great surprise that the coefficients of the above asymptotic series are found as 

\begin{eqnarray}
Z^{(0)}_n (m) &=& \frac{\Gamma\left(n+\frac{1}{2}\right)}{\pi^{\frac{3}{2}}}\, \sum_{k=0}^n (-1)^k\, \frac{\Gamma\left(k+\frac{1}{2}\right) \Gamma\left(n-k+\frac{1}{2}\right)}{\Gamma\left(k+1\right) \Gamma\left(n-k+1\right)}\, m^k\, m^{\prime\, n-k} \nonumber \\
&=& \frac{\Gamma^2\left(n+\frac{1}{2}\right)}{\pi\, \Gamma\left(n+1\right)}\, {}_2F_{1} \left( -n, -n, \frac{1}{2}-n\, \right| \left. \vphantom{\frac{1}{2}} m \right),
\end{eqnarray} 

\noindent
in precise agreement with expression \eqref{eq:elliptic_coeffs0}, which was derived from the recursion relations \eqref{ell_lin_rec}. Notice that, as expected from the discussion of section~\ref{sec:borel}, the form of the second integral in \eqref{JA} resembles the resummation of the Borel transform ${\cal B} [\Phi_0] (s)$, up to the extra factor of $1/\sqrt{x}$ in front. To deal with these extra factors and ``odd-looking'' Borel transforms, in section~\ref{sec:borel} we introduced sectors of the form $\Phi_{i,[\alpha]}(x) = x^{\alpha}\, \Phi_{i,[0]}(x)$ (recall \eqref{Phi_[gamma]-DEF}) where herein $\Phi_{i,[0]}(x)$ is any of the original asymptotic sectors $\Phi_i (x)$ whose Borel transforms have (simple) logarithmic singularities. Form \eqref{JA} one can now immediately identify

\begin{equation}
\Phi_{0,[1/2]}(x) = \frac{1}{\sqrt{\pi}} \int_{{\cal J}_0 (\theta)} {\mathrm{d}} z\, {\mathrm{e}}^{-\frac{1}{x}\, \mathrm{sd}^2 (z | m)},
\end{equation} 

\noindent
whose Borel transform is given by

\begin{equation}
{\cal B} [\Phi_{0,[1/2]}] (s) = \frac{1}{\sqrt{\pi s \left( 1 - m^\prime s \right) \left( 1 + m s \right)}}.
\end{equation}

The Borel transforms associated to sectors $\Phi_{i,[\alpha]}(x)$ for different $\alpha$ are related by a fractional derivative, via \eqref{eq:finding-Borel-rep-from-other}. As discussed in section~\ref{sec:borel}, and due to the involved fractional derivatives, these Borel transforms are related in highly non-local fashions. Although alien calculus might give preference to the choice $\alpha=0$, we shall demonstrate below that it may also be illuminating to work with $\alpha=1/2$. In fact, herein we will find a surprisingly simple relation between the Borel transforms of the series associated with the different critical points.

Similarly to \eqref{JA}, the integration over the thimble ${\cal J}_1(\theta)$ may be expressed as 

\begin{eqnarray}
\frac{1}{\sqrt{\pi x}} \int_{{\cal J}_1(\theta)} {\mathrm{d}} z\, {\mathrm{e}}^{-\frac{1}{x}\, \mathrm{sd}^2 (z | m)} &=& - \frac{1}{\sqrt{\pi x}} \int_{\frac{1}{m^\prime}}^{{\mathrm{e}}^{{\mathrm{i}}\theta}\infty} {\mathrm{d}} s\, \frac{{\mathrm{e}}^{-\frac{s}{x}}}{\sqrt{s \left( 1 - m^\prime s \right) \left( 1 + m s \right)}} \nonumber \\
&=& {\mathrm{i}}\, {\mathrm{e}}^{-\frac{1}{m^\prime x}}\, \frac{\sqrt{m^\prime}}{\sqrt{\pi x}}  \int_0^{{\mathrm{e}}^{{\mathrm{i}}\theta} \infty} {\mathrm{d}} s\, \frac{{\mathrm{e}}^{-\frac{s}{x}}}{\sqrt{s \left( 1 + m m^\prime s \right) \left( 1 + m^\prime s \right)}} \nonumber \\
&\equiv& {\mathrm{e}}^{-\frac{A_1}{x}}\, \frac{1}{\sqrt{x}}\, {\cal S}_\theta \Phi_{1,[1/2]} (x). 
\end{eqnarray}

\noindent
Notice that the integrand of the integral on the right-hand-side of the first line is precisely the Borel transform of $\Phi_{0,[1/2]}(x)$ (up to a shift $1/m^\prime$), while in the last line we obtain instead a resummation of $\Phi_{1,[1/2]}(x)$. Furthermore, the shift in question is precisely the relative action $A_0-A_1$. As we shall see next, this is a manifestation of resurgence: the two asymptotic series, attached to different critical points, are related by a simple shift in the Borel plane, where the shift is precisely the difference between the actions at those critical points. We can moreover write

\begin{equation}
{\cal B} [\Phi_{1,[1/2]}] (s) = \frac{{\mathrm{i}} \sqrt{m^\prime}}{\sqrt{\pi s \left( 1 + m m^\prime s \right) \left( 1 + m^\prime s \right)}}.
\end{equation}

\noindent
Finally, the  integration over the thimble ${\cal J}_2(\theta)$ can be expressed in a totally similar fashion as

\begin{eqnarray}
\frac{1}{\sqrt{\pi x}} \int_{{\cal J}_2(\theta)} {\mathrm{d}} z\, {\mathrm{e}}^{-\frac{1}{x}\, \mathrm{sd}^2 (z | m)} &=& - \frac{1}{\sqrt{\pi x}} \int_{-\frac{1}{m}}^{{\mathrm{e}}^{{\mathrm{i}}\theta} \infty} {\mathrm{d}} s\, \frac{{\mathrm{e}}^{-\frac{s}{x}}}{\sqrt{s \left( 1 - m^\prime s \right) \left( 1 + m s \right)}} \nonumber \\
&=& {\mathrm{i}}\, {\mathrm{e}}^{\frac{1}{m x}}\, \frac{\sqrt{m}}{\sqrt{\pi x}} \int_0^{{\mathrm{e}}^{{\mathrm{i}}\theta} \infty} {\mathrm{d}} s\, \frac{{\mathrm{e}}^{-\frac{s}{x}}}{\sqrt{s \left( 1 - m m^\prime s \right) \left( 1 - m s \right)}} \nonumber \\
&\equiv& {\mathrm{e}}^{-\frac{A_2}{x}}\, \frac{1}{\sqrt{x}}\, {\cal S}_\theta \Phi_{2,[1/2]} (x),
\end{eqnarray}

\noindent
where

\begin{equation}
{\cal B} [\Phi_{2,[1/2]}] (s) = \frac{{\mathrm{i}} \sqrt{m}}{\sqrt{\pi s \left( 1 - m m^\prime s \right) \left( 1 - m s \right)}}.
\end{equation}

It is now clear that the Borel transforms of the series associated with each critical point are related to each other in a strikingly simple way,

\begin{equation}
{\cal B} [\Phi_{i,[1/2]}] \left(s\right) = \pm {\cal B} [\Phi_{j,[1/2]}] \left(s-\left( A_j-A_i\right)\right), \qquad i,j=0,1,2,  
\end{equation}

\noindent
where the plus-sign occurs when $j=0$. In words: on the Borel plane, and up to a sign\footnote{This sign is governed by the branch of the square-root one goes through when performing the shift.}, these Borel transforms are expressed by the exact \textit{same function}, only shifted by the relative action $A_j-A_i$. An immediate consequence of this relation is that, having access to, say, the perturbative asymptotic series around the vacuum, one can then reconstruct the expansions around \textit{all} other nonperturbative sectors without much effort. Further recalling the expected general relations between such Borel transforms, \eqref{eq:B_Psi_n:d=odd}, we can proceed to read-off the values of the Borel residues and then of the Stokes coefficients $S_{\omega_{ij}}$ in \eqref{ell-linear-aliender-1}--\eqref{ell-linear-aliender-3}. These numbers agree with the ones obtained in \eqref{eq:linear-stokes}. These very same values can also be obtained from a large-order analysis of the asymptotic behaviour of the coefficients $Z^{(i)_n}$, to which we turn next.

Asymptotics and Large-Order Behaviour: Partition Function
\label{sec:linear_ode}


Let us now turn to the analysis of the large-order behaviour of the partition-function coefficients $Z^{(i)}_n$. For concreteness, let us start with the perturbative sector.  Using the connection formula for the hypergeometric function, one can write 

\begin{equation}
\label{eq:linear-ell-lo}
Z^{(0)}_n (m) = \frac{\Gamma\left(n+1\right)}{\pi \left( n+\frac{1}{2} \right)} \left\{ \left( m^\prime \right)^{n+\frac{1}{2}}\, {}_2F_{1} \left( \frac{1}{2}, \frac{1}{2}, \frac{3}{2}+n\, \right| \left. \vphantom{\frac{1}{2}} m^\prime \right) + (-1)^n\, m^{n+\frac{1}{2}}\, {}_2F_{1} \left( \frac{1}{2}, \frac{1}{2}, \frac{3}{2}+n\, \right| \left. \vphantom{\frac{1}{2}} m \right) \right\}. 
\end{equation}

\noindent
This decomposition of the perturbative coefficients already hints that they must somehow relate to nonperturbative content, since $A_1 = \left( m^\prime \right)^{-1}$ and $A_2 = - m^{-1}$. Of course such relations may be made very precise via resurgence. But before we do that, let us proceed by expanding the above hypergeometric functions in both $m^{\prime}$ and $m$,

\begin{eqnarray}
\label{ell_pertecomp}
Z^{(0)}_n (m) &\simeq& \frac{\Gamma\left(n+1\right)}{\pi \left( 2n+1 \right)} \left\{ \left(m^\prime\right)^{n+\frac{1}{2}} \left( 2 + \frac{m^\prime}{2n+3} +\frac{9 \left( m^\prime \right)^2}{4 \left( 2n+3 \right) \left( 2n+5 \right)} + \cdots \right) + \right. \\
&&
\hspace{65pt}
\left. + (-1)^n\, m^{n+\frac{1}{2}} \left( 2 + \frac{m}{2n+3} + \frac{9 \left( m \right)^2}{4 \left( 2n+3 \right) \left( 2n+5 \right)} + \cdots \right) \right\}. \nonumber
\end{eqnarray} 

\noindent
This expansion is valid for any $n$; in particular one can take the limit $n\gg1$ and reorganize the several terms as

\begin{eqnarray}
Z^{(0)}_n (m) &\simeq& \frac{\left( m^\prime \right)^{n+\frac{1}{2}}\, \Gamma\left(n\right)}{\pi} \left( 1 - \frac{1}{2n} + \frac{1}{4n^2} + \cdots + \frac{m^\prime}{4n} - \frac{m^\prime}{2n^2} + \cdots + \frac{9 \left(m^\prime\right)^2}{32n^2} + \cdots \right) + \nonumber \\
&+& \frac{(-1)^n\, m^{n+\frac{1}{2}}\, \Gamma\left(n\right)}{\pi} \left( 1 - \frac{1}{2n} + \frac{1}{4n^2} + \cdots + \frac{m}{4n} - \frac{m}{2n^2} + \cdots + \frac{9\, m^2}{32n^2} + \cdots \right) \\
&\approx& \frac{\left( m^\prime \right)^{n} \Gamma\left(n\right)}{\pi} \left( \sqrt{m^\prime} - \sqrt{m^\prime}\, \frac{m^\prime-2}{4 \left(n-1\right)} + \sqrt{m^\prime}\, \frac{9 \left(m^\prime\right)^2 - 24\, m^\prime + 24}{32 \left(n-1\right) \left(n-2\right)} + \cdots \right) + \nonumber \\
&+& \frac{(-1)^n\, m^{n}\, \Gamma\left(n\right)}{\pi} \left( \sqrt{m} - \sqrt{m}\, \frac{m-2}{4 \left(n-1\right)} + \sqrt{m}\, \frac{9\, m^2 - 24\, m + 24}{32 \left(n-1\right) \left(n-2\right)} + \cdots \right).
\end{eqnarray} 

\noindent
Interestingly enough, this form already is \textit{precisely} the expected large-order behaviour for the perturbative series, usually written as

\begin{eqnarray}
Z^{(0)}_n (m) &\simeq& \frac{2}{2\pi{\mathrm{i}}}\, \frac{\Gamma\left(n\right)}{A_1^n} \left( Z^{(1)}_0 + \frac{A_1}{n-1}\, Z^{(1)}_1 + \frac{A_1^2}{\left(n-1\right) \left(n-2\right)}\, Z^{(1)}_2 + \cdots \right) + \nonumber \\
&+& \frac{2}{2\pi{\mathrm{i}}}\, \frac{\Gamma\left(n\right)}{A_2^n} \left( Z^{(2)}_0 + \frac{A_2}{n-1}\, Z^{(2)}_1 + \frac{A_2^2}{\left(n-1\right) \left(n-2\right)}\, Z^{(2)}_2 + \cdots \right). 
\label{large_order_aA}
\end{eqnarray}

The standard approach---which in fact allows for a determination of the large-order relations associated to \textit{all} (perturbative and nonperturbative) sectors---is to follow the same steps as in subsection~\ref{subsec:Zasymptotics}. From Cauchy's theorem, 

\begin{equation}
\Phi_i (x) = -\frac{1}{2\pi{\mathrm{i}}}\, \sum_{\theta=0,\pi}\, \int_0^{{\mathrm{e}}^{{\mathrm{i}}\theta} \infty} {\mathrm{d}} w\, \frac{\disc_\theta \Phi_i(w)}{w-x},
\end{equation}

\noindent
where the discontinuity is defined by \eqref{StokesDisc} and the relevant Stokes automorphisms are given in \eqref{ell-linear-Stokes-00}--\eqref{ell-linear-Stokes-02}. For $\Phi_0$, it follows

\begin{equation}
\sum_{n=0}^{+\infty} Z^{(0)}_n\, x^n \simeq \frac{S_{\omega_{01}}}{2\pi\mathrm{i}}\, \int_0^{+\infty} \mathrm{d}w\, \frac{1}{w-x}\, \mathrm{e}^{-\frac{A_1}{w}}\, \sum_{k=0}^{+\infty} Z^{(1)}_k\, w^k + \frac{S_{\omega_{02}}}{2\pi\mathrm{i}}\, \int_0^{-\infty} \mathrm{d}w\, \frac{1}{w-x}\, \mathrm{e}^{-\frac{A_2}{w}}\, \sum_{k=0}^{+\infty}Z^{(2)}_k\,w^k,
\end{equation}

\noindent
leading to

\begin{equation}
\label{large_order_aA-v2}
Z^{(0)}_n \simeq \frac{S_{\omega_{01}}}{2\pi\mathrm{i}}\, \frac{\Gamma\left(n\right)}{A_1^n}\, \sum_{k=0}^{+\infty} \frac{\Gamma\left(n-k\right)}{\Gamma\left(n\right)}\, A_1^k\, Z^{(1)}_k + \frac{S_{\omega_{02}}}{2\pi\mathrm{i}}\, \frac{\Gamma\left(n\right)}{A_2^n}\, \sum_{k=0}^{+\infty} \frac{\Gamma\left(n-k\right)}{\Gamma\left(n\right)}\, A_2^k\, Z^{(2)}_k.
\end{equation}

\noindent
This exactly matches \eqref{large_order_aA}, once the Stokes coefficients are identified as $S_{\omega_{01}}=S_{\omega_{02}}=2$.

Let us take another look at \eqref{large_order_aA} or \eqref{large_order_aA-v2}. It is clear that the large-order coefficients in the perturbative expansion are dominated at next-to-leading order by the nearest action to the origin, which, depending on whether $m<1/2$ or $m>1/2$, is either $A_1$ or $A_2$. However, at the special point where $m=1/2=m^\prime$ both instanton actions will contribute \textit{symmetrically}. In particular, this will cause all the \textit{odd} powers $Z^{(0)}_{2\BN+1}$ to \textit{vanish} (which can already be seen directly from \eqref{eq:linear-ell-lo}). This is a particular case of resonant behaviour, where $A_1+A_2=0$.

The large-order behaviours of the series $\Phi_1$ and $\Phi_2$ can be determined in the exact same way. Repeating such familiar procedure, the large-order growth of $\Phi_1$ is found to be

\begin{eqnarray}
\label{large_order_aB}
Z^{(1)}_n (m) &\simeq& \frac{S_{\omega_{10}}}{2\pi\mathrm{i}}\, \frac{\Gamma\left(n\right)}{\left(-A_1\right)^n} \left( Z^{(0)}_0 + \frac{-A_1}{n-1}\, Z^{(0)}_1 + \frac{\left(-A_1\right)^2}{\left(n-1\right) \left(n-2\right)}\, Z^{(0)}_2 + \cdots \right) + \\
&&
\hspace{-30pt}
+ \frac{S_{\omega_{12}}+\frac{1}{2}S_{\omega_{02}}S_{\omega_{10}}}{2\pi \mathrm{i}}\, \frac{\Gamma\left(n\right)}{\left(A_2-A_1\right)^n} \left( Z^{(2)}_0 + \frac{A_2-A_1}{n-1}\, Z^{(2)}_1 + \frac{\left(A_2-A_1\right)^2}{\left(n-1\right) \left(n-2\right)}\, Z^{(2)}_2 + \cdots \right).
\nonumber 
\end{eqnarray}

\noindent
Recall that $S_{\omega_{10}}=-2$ and $S_{\omega_{12}}+\frac{1}{2}S_{\omega_{02}}S_{\omega_{10}}=-2$. Further recall that $-A_1$ is actually the relative action $A_0-A_1$, where $A_0=0$ is the ``perturbative action''. Both relative actions $A_0-A_1$ and $A_2-A_1$ are negative, in which case $\Phi_1$ only has Borel singularities along the negative real axis. Similarly, the large-order growth of $\Phi_2$ is

\begin{eqnarray}
Z^{(2)}_n (m) &\simeq& \frac{S_{\omega_{20}}}{2\pi\mathrm{i}}\, \frac{\Gamma\left(n\right)}{\left(-A_2\right)^n} \left( Z^{(0)}_0 + \frac{-A_2}{n-1}\, Z^{(0)}_1 + \frac{\left(-A_2\right)^2}{\left(n-1\right) \left(n-2\right)}\, Z^{(0)}_2 + \cdots \right) + \\
&&
\hspace{-30pt}
+ \frac{S_{\omega_{21}}+\frac{1}{2}S_{\omega_{01}}S_{\omega_{20}}}{2\pi \mathrm{i}}\, \frac{\Gamma\left(n\right)}{\left(A_1-A_2\right)^n} \left( Z^{(1)}_0 + \frac{A_1-A_2}{n-1}\, Z^{(1)}_1 + \frac{\left(A_1-A_2\right)^2}{\left(n-1\right) \left(n-2\right)}\, Z^{(1)}_2 + \cdots \right).
\nonumber
\end{eqnarray}

\noindent
Herein one should recall that $S_{\omega_{20}}=-2$ and $S_{\omega_{21}}+\frac{1}{2}S_{\omega_{01}}S_{\omega_{20}}=-2$. Further, and in contrast to $\Phi_1$, the Borel singularities of $\Phi_2$ are now located along the positive real axis. In summary, we have made it rather explicit how the large-order behaviour of \textit{each} formal series $\Phi_i$ is controlled by the relative actions with respect to the \textit{other} critical points. The most dominant contribution always comes from the nearest critical point $j$ such that $|A_j-A_i|$ is the smallest. Furthermore, for $x\in\mathbb R^+$, if $A_j>A_i$ then the contribution of the critical point $j$ to the large-order growth of $i$ is non-alternating whereas for $A_j<A_i$ it is alternating.  

In linear examples we are fortunate to have closed-form expressions for the asymptotic-series coefficients, from which one may analyze large-order behaviours without resorting to numerical calculations. In most nonlinear examples, however, this is not the case and asymptotic-series coefficients can only be computed recursively up to some fixed given order. Nevertheless, we have learnt in section~\ref{sec:quartic} how to fit the large-order behaviour predicted by resurgence to such recursive (numerical) data; and in this way extract the values of the Stokes coefficients. In the present (simple) linear scenario, figure~\ref{fig:large_order} illustrates such fit. On the left image, we plot the coefficients $Z^{(0)}_n$ weighted by the growth factor $2\pi A_1^n/\Gamma\left(n\right)$, and show the convergence towards the predicted value  \eqref{large_order_aA}, given by $-S_{\omega_{01}} \mathrm{i}\, Z^{(1)}_0 = 2\sqrt{1-m}$ (where in the plot we set $m=\pi/8$). For our choice of $m$, the large-order growth is dominated by the critical point $z^*_1$ since $A_1<|A_2|$. In order to numerically check the exponentially-suppressed contributions associated with $A_2$ in \eqref{large_order_aA}, we first need to resum the asymptotic large-order series\footnote{See subsection~\ref{sec:large-order-F} for definitions and a thorough introduction to this whole procedure.}

\begin{equation}
\chi_{0\rightarrow1}(n) \simeq \sum_{k=0}^{+\infty} \frac{\Gamma\left(n-k\right)}{\Gamma\left(n\right)}\, A_1^k\, Z^{(1)}_k.
\end{equation}

\noindent
With this result in hand one may then plot the weighted resummation

\begin{equation}
\label{ell-partfunc-resummed}
\delta Z^{(0)}_n \equiv \left( Z^{(0)}_n\, \frac{2\pi A_1^n}{\Gamma\left(n\right)} - \left( -\mathrm{i} S_{\omega_{01}} \right) \mathcal{S}_0 \mathrm{BP}_{100} \left[\chi_{0\rightarrow1}(n)\right] \right) \left( \frac{A_2}{A_1} \right)^n,
\end{equation}

\noindent
which is done on the right-hand plot of figure~\ref{fig:large_order} (and where $\mathrm{BP}_{100} \left[\chi_{0\rightarrow1}(n)\right]$ is the resummed Borel--Pad\'{e} approximant associated to the series $\chi_{0\rightarrow1}(n)$). We can very clearly see the convergence towards the expected value, $-S_{\omega_{02}} \mathrm{i}\, Z^{(2)}_0 = 2\sqrt{m}$.


\begin{figure}[t!]
\begin{center}
\includegraphics[height=5.1cm]{elliptic-partfunc-leading.pdf}
$\qquad$
\includegraphics[height=5.1cm]{elliptic-partfunc-borel-pade.pdf}
\end{center}
\caption{Numerical plots of the asymptotic large-order growth of the perturbative series coefficients, $Z_n^{(0)}$ (left), and its subleading exponentially-suppressed growth (right), as predicted by \eqref{large_order_aA} (with $m=\pi/8$ in the plots). On the left we plot the coefficients $Z_n^{(0)}$ weighted by their growth factor (in red), together with the corresponding fifth Richardson transform (in blue). The sequence is seen to converge to the predicted value $-S_{\omega_{01}} \mathrm{i}\, Z^{(1)}_0 = 2\sqrt{1-m}$ (in purple). On the right we plot the weighted resummation \eqref{ell-partfunc-resummed} (in red), the corresponding fifth Richardson transform (in blue), and the predicted value of convergence, $-S_{\omega_{02}} \mathrm{i}\, Z^{(2)}_0 = 2\sqrt{m}$ (in purple). The errors associated with this numerical calculation are $\sim\mathcal{O}(10^{-13})$.}
